ALTER TABLE "youtube_discovery_candidates" DROP CONSTRAINT "youtube_discovery_candidates_metadata_check";--> statement-breakpoint
ALTER TABLE "youtube_discovery_candidates" ADD CONSTRAINT "youtube_discovery_candidates_metadata_check" CHECK (("channel_id" IS NULL OR "channel_id" ~ '^[A-Za-z0-9_-]{6,64}$') AND ("category_id" IS NULL OR "category_id" ~ '^[0-9]{1,8}$') AND ("duration_seconds" IS NULL OR "duration_seconds" BETWEEN 0 AND 86400) AND ("view_count" IS NULL OR "view_count" >= 0) AND ("like_count" IS NULL OR "like_count" >= 0) AND ("comment_count" IS NULL OR "comment_count" >= 0) AND ("channel_subscriber_count" IS NULL OR "channel_subscriber_count" >= 0) AND ("thumbnail_url" IS NULL OR (char_length("thumbnail_url") <= 500 AND "thumbnail_url" !~ '[\x00-\x1F\x7F]' AND "thumbnail_url" ~ '^https://(i\.ytimg\.com|img\.youtube\.com)/[^[:space:]]+$')));
